<?php require 'config.php';require_login();if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['add'])){$pid=(int)$_POST['product_id'];$qty=max(1,(int)($_POST['quantity']??1));$s=$pdo->prepare('SELECT stock FROM products WHERE id=?');$s->execute([$pid]);$p=$s->fetch();if(!$p||$p['stock']<$qty){flash('สินค้าไม่พอในสต็อก');}else{$pdo->prepare('INSERT INTO cart_items(user_id,product_id,quantity) VALUES(?,?,?) ON DUPLICATE KEY UPDATE quantity=quantity+VALUES(quantity)')->execute([user()['id'],$pid,$qty]);flash('เพิ่มสินค้าลงตะกร้าแล้ว');}header('Location: cart.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['update'])){$id=(int)$_POST['item_id'];$qty=max(1,(int)$_POST['quantity']);$pdo->prepare('UPDATE cart_items SET quantity=? WHERE id=? AND user_id=?')->execute([$qty,$id,user()['id']]);header('Location: cart.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['remove'])){$pdo->prepare('DELETE FROM cart_items WHERE id=? AND user_id=?')->execute([(int)$_POST['item_id'],user()['id']]);header('Location: cart.php');exit;}require 'header.php';$s=$pdo->prepare('SELECT ci.id,ci.quantity,p.name,p.price,p.stock,p.image FROM cart_items ci JOIN products p ON p.id=ci.product_id WHERE ci.user_id=?');$s->execute([user()['id']]);$items=$s->fetchAll();$total=0;foreach($items as $i)$total+=$i['price']*$i['quantity'];?>
<div class="container"><h1>ตะกร้าสินค้า</h1><?php if(!$items):?><div class="empty">ตะกร้าของคุณยังว่าง <a href="index.php" style="color:var(--orange)">ไปเลือกสินค้า</a></div><?php else:?><div class="table-wrap"><table><thead><tr><th>สินค้า</th><th>ราคา</th><th>จำนวน</th><th>รวม</th><th></th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=h($i['name'])?></td><td>฿<?=money($i['price'])?></td><td><form class="inline" method="post"><input type="hidden" name="update" value="1"><input type="hidden" name="item_id" value="<?=$i['id']?>"><input style="width:80px" type="number" min="1" max="<?=$i['stock']?>" name="quantity" value="<?=$i['quantity']?>"><button class="btn secondary">ปรับ</button></form></td><td>฿<?=money($i['price']*$i['quantity'])?></td><td><form method="post"><input type="hidden" name="remove" value="1"><input type="hidden" name="item_id" value="<?=$i['id']?>"><button class="btn danger">ลบ</button></form></td></tr><?php endforeach;?></tbody></table></div><div class="panel" style="max-width:420px;margin-left:auto"><h2>ยอดรวม ฿<?=money($total)?></h2><a class="btn" href="checkout.php">ดำเนินการสั่งซื้อ</a></div><?php endif;?></div><?php require 'footer.php';?>
